/*
 * Tree files support:
 *
 * An export can be stored as a tree of small block files rather than one
 * big file; see the treefiles option in nbd-server(5). The export is
 * split into TREEPAGESIZE-byte blocks; each directory holds at most
 * TREEDIRSIZE files or subdirectories, named by the base-TREEDIRSIZE
 * digits of the block number (TREEXXXX for directories, FILEXXXX for
 * the block files themselves).
 */

#include "config.h"
#include "lfs.h"

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>

#include <sys/stat.h>
#include <sys/types.h>

#include "nbd-debug.h"
#include "nbdsrv.h"
#include "treefiles.h"

/**
 * Compute the number of directory levels needed to store an export of
 * size bytes with at most TREEDIRSIZE entries per directory.
 **/
static int tree_levels(off_t size) {
	int levels = 1;
	off_t capacity = TREEDIRSIZE;
	off_t blocks = (size + TREEPAGESIZE - 1) / TREEPAGESIZE;

	while (capacity < blocks) {
		levels++;
		capacity *= TREEDIRSIZE;
	}
	return levels;
}
```

