/**
 * Create all directories in path, like `mkdir -p'.
 * path may be modified.
 **/
void mkdir_path(char *path) {
	char *p = path;

	if (*p == '/')
		p++;
	while ((p = strchr(p, '/'))) {
		*p = '\0';
		(void)mkdir(path, 0700);
		*p = '/';
		p++;
	}
