```c
/**
 * Open the block file holding byte pos of an export.
 *
 * @param name the exportname (root of the tree)
 * @param mode open(2) flags; with O_CREAT, missing directories and file are created
 * @param size total size of the export
 * @param pos offset into the export
 * @param mutex serializes file and directory creation
 * @return file descriptor, or -1 on error
 **/
int open_treefile(char *name, mode_t mode, off_t size, off_t pos, pthread_mutex_t *mutex) {
	char path[PATH_MAX];
	char dir[PATH_MAX];
	off_t ppos;
	char *slash;
	int fd;

	if (strlen(name) >= sizeof(path)) {
		errno = ENAMETOOLONG;
		return -1;
	}
	strcpy(path, name);
	construct_path(path, sizeof(path), size, pos, &ppos);

	if (!(mode & O_CREAT))
		return open(path, mode);

	pthread_mutex_lock(mutex);
	strcpy(dir, path);
	slash = strrchr(dir, '/');
	if (slash) {
		*slash = '\0';
		mkdir_path(dir);
	}
	fd = open(path, mode, 0600);
	pthread_mutex_unlock(mutex);
	return fd;
}
