/**
 * Read from a tree of block files. Blocks whose file does not exist
 * read as zeroes.
 *
 * @return number of bytes read, or -1 on error
 **/
ssize_t tree_read(off_t a, char *buf, size_t len, CLIENT *client) {
	size_t ret = len;

	while (len > 0) {
		off_t ppos = a % TREEPAGESIZE;
		size_t chunk = TREEPAGESIZE - ppos;
		if (chunk > len)
			chunk = len;

		int fd = open_treefile(client->exportname, O_RDONLY, client->exportsize, a, &client->tree_lock);
		if (fd < 0) {
			if (errno != ENOENT)
				return -1;
			memset(buf, 0, chunk);
		} else {
			ssize_t r = pread(fd, buf, chunk, ppos);
			close(fd);
			if (r < 0)
				return -1;
			/* the last block file may be shorter than a full block */
			memset(buf + r, 0, chunk - r);
		}
		a += chunk;
		buf += chunk;
		len -= chunk;
	}
	return ret;
}
