/**
 * Write to a tree of block files, creating block files and their
 * directories on demand. Writing zeroes to a full block deletes the
 * block file again, keeping the tree sparse.
 *
 * @return number of bytes written, or -1 on error
 **/
ssize_t tree_write(off_t a, char *buf, size_t len, CLIENT *client, int fua) {
	size_t ret = len;

	while (len > 0) {
		off_t ppos = a % TREEPAGESIZE;
		size_t chunk = TREEPAGESIZE - ppos;
		if (chunk > len)
			chunk = len;

		if (ppos == 0 && chunk == TREEPAGESIZE && tree_block_is_zero(buf)) {
			/* a fully zeroed block is the same as an absent one */
			delete_treefile(client->exportname, client->exportsize, a);
		} else {
			int fd = open_treefile(client->exportname, O_RDWR | O_CREAT, client->exportsize, a, &client->tree_lock);
			if (fd < 0)
				return -1;
			ssize_t w = pwrite(fd, buf, chunk, ppos);
			if (w == (ssize_t)chunk) {
				if (client->server->flags & F_SYNC)
					fsync(fd);
				else if (fua)
					fdatasync(fd);
			}
			close(fd);
			if (w != (ssize_t)chunk)
				return -1;
		}
		a += chunk;
		buf += chunk;
		len -= chunk;
	}
	return ret;
}
