/*
 * Tree files support.
 *
 * An export can be stored as a tree of small block files instead of a
 * single big file; see the "treefiles" option in nbd-server(5). The
 * export is split into TREEPAGESIZE-byte blocks, and no directory holds
 * more than TREEDIRSIZE entries. The path of a block is formed from the
 * digits of its block number in base TREEDIRSIZE: intermediate
 * directories are named TREEXXXX and the block files themselves
 * FILEXXXX, where XXXX is the respective digit.
 */

#include "config.h"
#include "lfs.h"

#include <assert.h>
#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <stdbool.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

#include <sys/stat.h>
#include <sys/types.h>

#include "nbd-debug.h"
#include "nbdsrv.h"
#include "treefiles.h"

/**
 * Compute the number of directory levels needed to store an export of
 * the given size with at most TREEDIRSIZE entries per directory.
 *
 * @param size total size of the export
 * @return number of levels; 1 means the block files live in the root
 * of the tree
 **/
static int tree_levels(off_t size) {
	int levels = 1;
	off_t capacity = TREEDIRSIZE;
	off_t blocks = (size + TREEPAGESIZE - 1) / TREEPAGESIZE;

	while (capacity < blocks) {
		levels++;
		capacity *= TREEDIRSIZE;
	}
	return levels;
}

/**
 * Append the path of the block file holding the byte at pos to name.
 *
 * @param name buffer holding the exportname on entry; the relative
 * path of the block file is appended on return
 * @param lenmax total size of the name buffer
 * @param size total size of the export
 * @param pos offset into the export
 * @param ppos [out] offset of pos into its block file
 **/
void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	int levels = tree_levels(size);
	/* an off_t-sized export never needs more than 6 levels */
	int digits[8];
	off_t block = pos / TREEPAGESIZE;
	int used = strlen(name);
	char *p = name + used;
	int rem = lenmax - used;
	int i, n;

	*ppos = pos % TREEPAGESIZE;

	assert(levels <= (int)(sizeof(digits)/sizeof(digits[0])));
	for (i = 0; i < levels; i++) {
		digits[i] = block % TREEDIRSIZE;
		block /= TREEDIRSIZE;
	}

	for (i = levels - 1; i >= 0; i--) {
		if (rem <= 0)
			return;
		n = snprintf(p, rem, "%s%04d", i ? "/TREE" : "/FILE", digits[i]);
		if (n < 0)
			return;
		if (n >= rem)
			n = rem - 1;
		p += n;
		rem -= n;
	}
}

/**
 * Create all directories in path, like `mkdir -p'. The path may be
 * temporarily modified.
 *
 * @param path the directory path to create
 **/
void mkdir_path(char *path) {
	char *p = path;

	if (*p == '/')
		p++;
	while ((p = strchr(p, '/'))) {
		*p = '\0';
		(void)mkdir(path, 0700);
		*p++ = '/';
	}
	(void)mkdir(path, 0700);
}

/**
 * Open the block file holding the byte at pos of an export.
 *
 * @param name the exportname, i.e. the root of the tree
 * @param mode open(2) flags; with O_CREAT, missing directories and the
 * file itself are created
 * @param size total size of the export
 * @param pos offset into the export
 * @param mutex serializes file and directory creation
 * @return a file descriptor, or -1 in case of an error
 **/
int open_treefile(char *name, mode_t mode, off_t size, off_t pos, pthread_mutex_t *mutex) {
	char path[PATH_MAX];
	char dir[PATH_MAX];
	off_t ppos;
	char *slash;
	int fd;

	if (strlen(name) >= sizeof(path)) {
		errno = ENAMETOOLONG;
		return -1;
	}
	strcpy(path, name);
	construct_path(path, sizeof(path), size, pos, &ppos);

	if (!(mode & O_CREAT))
		return open(path, mode);

	pthread_mutex_lock(mutex);
	strcpy(dir, path);
	slash = strrchr(dir, '/');
	if (slash) {
		*slash = '\0';
		mkdir_path(dir);
	}
	fd = open(path, mode, 0600);
	pthread_mutex_unlock(mutex);
	return fd;
}

/**
 * Delete the block file holding the byte at pos of an export. A file
 * that does not exist is considered deleted already.
 *
 * @param name the exportname, i.e. the root of the tree
 * @param size total size of the export
 * @param pos offset into the export
 **/
void delete_treefile(char *name, off_t size, off_t pos) {
	char path[PATH_MAX];
	off_t ppos;

	if (strlen(name) >= sizeof(path))
		return;
	strcpy(path, name);
	construct_path(path, sizeof(path), size, pos, &ppos);
	(void)unlink(path);
}

static bool tree_block_is_zero(const char *buf, size_t len) {
	size_t i;

	for (i = 0; i < len; i++) {
		if (buf[i])
			return false;
	}
	return true;
}

ssize_t tree_read(off_t a, char *buf, size_t len, CLIENT *client) {
	size_t ret = len;

	while (len > 0) {
		off_t ppos = a % TREEPAGESIZE;
		size_t chunk = TREEPAGESIZE - ppos;
		if (chunk > len)
			chunk = len;

		int fd = open_treefile(client->exportname, O_RDONLY,
				client->exportsize, a, &client->tree_lock);
		if (fd < 0) {
			if (errno != ENOENT)
				return -1;
			memset(buf, 0, chunk);
		} else {
			ssize_t r = pread(fd, buf, chunk, ppos);
			close(fd);
			if (r < 0)
				return -1;
			/* the last block file may be shorter than a
			 * full block */
			memset(buf + r, 0, chunk - r);
		}
		a += chunk;
		buf += chunk;
		len -= chunk;
	}
	return ret;
}

ssize_t tree_write(off_t a, char *buf, size_t len, CLIENT *client, int fua) {
	size_t ret = len;

	while (len > 0) {
		off_t ppos = a % TREEPAGESIZE;
		size_t chunk = TREEPAGESIZE - ppos;
		if (chunk > len)
			chunk = len;

		if (ppos == 0 && chunk == TREEPAGESIZE &&
				tree_block_is_zero(buf, chunk)) {
			/* a fully zeroed block is the same as an
			 * absent one, so mark it unused */
			delete_treefile(client->exportname,
					client->exportsize, a);
		} else {
			int fd = open_treefile(client->exportname,
					O_RDWR | O_CREAT, client->exportsize,
					a, &client->tree_lock);
			if (fd < 0)
				return -1;
			ssize_t w = pwrite(fd, buf, chunk, ppos);
			if (w == (ssize_t)chunk) {
				if (client->server->flags & F_SYNC)
					fsync(fd);
				else if (fua)
					fdatasync(fd);
			}
			close(fd);
			if (w != (ssize_t)chunk)
				return -1;
		}
		a += chunk;
		buf += chunk;
		len -= chunk;
	}
	return ret;
}

void tree_trim(off_t from, off_t len, CLIENT *client) {
	off_t end = from + len;
	off_t a;

	/* only delete files of blocks fully covered by the range; the
	 * NBD protocol defines no content for partially trimmed blocks */
	a = ((from + TREEPAGESIZE - 1) / TREEPAGESIZE) * TREEPAGESIZE;
	for (; a + TREEPAGESIZE <= end; a += TREEPAGESIZE) {
		delete_treefile(client->exportname, client->exportsize, a);
	}
	DEBUG("Performed TRIM request from %llu to %llu",
	      (unsigned long long)from, (unsigned long long)len);
}
